namespace {
void document_preserved(const Scene &before,const Scene &after,const detail::SourceRestGraph &graph){
 for(const auto &part:graph.parts){const auto &a=before.object(part.object),&b=after.object(part.object);
  check(a.painted->mesh_owner()==b.painted->mesh_owner()&&a.painted->encode()==b.painted->encode()&&a.material_bindings==b.material_bindings,"Detached Document snapshots retain the same immutable mesh and exact source paint/material data");
  if(part.original_skin<0){check(before.world_matrix(part.object).matrix()==after.world_matrix(part.object).matrix()&&a.deformation==b.deformation,"Actual native source REST leaves true rigid mesh/morph/world placement exact");continue;}
  const auto old=a.deformation->skeleton->skin_matrices(a.deformation->pose),now=b.deformation->skeleton->skin_matrices(b.deformation->pose);
  for(size_t joint=0;joint<old.size();++joint){const auto x=before.world_matrix(part.object)*AffineTransform(old[joint]),y=after.world_matrix(part.object)*AffineTransform(now[joint]);for(size_t k=0;k<16;++k)if(std::abs(x.matrix()[k]-y.matrix()[k])>2e-5)throw std::runtime_error("Independent actual Document per-skin WORLD product mismatch");}
  check(true,"Actual native source worker retains each skin's independent WORLD products");
 }
}
}
